export default function ExpertPage() {
  const [data, setData] = useState<ExpertResponse | null>(null);
  const [error, setError] = useState<string | null>(null);

  function load() {
    api<ExpertResponse>("/expert/tasks").then(setData).catch((err) => setError(err.message));
  }

  useEffect(load, []);

  async function complete(task: ExpertTask) {
    await api(`/expert/tasks/${task.id}`, { method: "PATCH", body: { status: "已完成" } });
    load();
  }

  return (
    <AsyncState loading={!data && !error} error={error}>
      {data && (
        <section className="page-stack">
          <div className="page-heading">
            <span className="eyebrow">Expert Workbench</span>
            <h2>专家工作台</h2>
