          </div>
          <div className="expert-layout">
            <section className="panel">
              <h3>任务池</h3>
              {data.tasks.map((task) => (
                <article className="expert-task" key={task.id}>
                  <div>
                    <span>{task.type} · {task.priority}优先级 · {task.due}</span>
                    <h3>{task.title}</h3>
                    <div className="bar"><i style={{ width: `${task.difficulty}%` }} /></div>
                  </div>
                  <div>
                    <StatusBadge value={task.status} />
                    <button onClick={() => complete(task)}>提交处理</button>
                  </div>
                </article>
              ))}
            </section>
            <aside className="panel">
              <h3>专家榜单</h3>
              {data.leaderboard.map((person, index) => (
