  justify-content: end;
}

.trend-chart i {
  background: linear-gradient(180deg, var(--cyan), var(--blue));
  border-radius: 999px 999px 8px 8px;
  display: block;
  min-height: 28px;
  width: 42px;
}

.timeline {
  display: grid;
  gap: 14px;
  margin-top: 18px;
}

.timeline div {
  align-items: flex-start;
  background: rgba(255, 255, 255, 0.04);
  border: 1px solid var(--line);
  border-radius: 18px;
  display: grid;
  gap: 14px;
  grid-template-columns: 42px 1fr;
  padding: 14px;
}

.timeline span {
  align-items: center;
  background: rgba(55, 215, 196, 0.15);
  border-radius: 14px;
  color: var(--cyan);
  display: flex;
  font-weight: 900;
  height: 42px;
  justify-content: center;
}

.timeline p {
  margin: 0;
}

.workflow-chain {
  display: grid;
  gap: 12px;
}

.workflow-chain div {
  align-items: center;
  background: rgba(255, 255, 255, 0.04);
  border: 1px solid var(--line);
  border-radius: 18px;
  display: grid;
  gap: 10px;
  grid-template-columns: 1fr 120px auto;
  padding: 14px;
}

.workflow-chain span {
  color: var(--muted);
}

.loop-grid {
  display: grid;
  gap: 12px;
  grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
}

.loop-grid article {
  background: linear-gradient(180deg, rgba(55, 215, 196, 0.1), rgba(255, 255, 255, 0.035));
  border: 1px solid var(--line);
  border-radius: 18px;
  display: grid;
  gap: 10px;
  padding: 16px;
  position: relative;
}

.loop-grid article:not(:last-child)::after {
  color: var(--cyan);
  content: "→";
  font-size: 22px;
  position: absolute;
  right: -16px;
  top: 42%;
}

.hero.compact {
  align-items: center;
  display: flex;
  gap: 12px;
  justify-content: flex-end;
  min-height: auto;
  padding: 0;
}

.user-pill,
.history-row,
.note-card,
.role-card,
.option-card,
.step-bar span,
.inline-notice,
.success-panel,
.login-form label,
.wizard-form label {
  display: block;
}

.user-pill {
  background: rgba(255, 255, 255, 0.06);
  border: 1px solid var(--line);
  border-radius: 999px;
  color: var(--text);
  padding: 10px 16px;
  text-decoration: none;
  white-space: nowrap;
}

.topbar {
  align-items: center;
  display: flex;
  gap: 16px;
  justify-content: space-between;
}

.login-page {
  margin: 0 auto;
  max-width: 720px;
  min-height: 100vh;
  padding: 48px 24px;
}

.login-hero {
  margin-bottom: 20px;
}

.login-form,
.wizard-form {
  display: grid;
  gap: 16px;
}

.login-form input,
.wizard-form input,
.wizard-form textarea {
  background: rgba(255, 255, 255, 0.04);
  border: 1px solid var(--line);
  border-radius: 14px;
  color: var(--text);
  margin-top: 8px;
  padding: 12px 14px;
  width: 100%;
}

.role-grid,
.option-grid {
  display: grid;
  gap: 12px;
  grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
}

.role-card,
.option-card {
  background: rgba(255, 255, 255, 0.04);
  border: 1px solid var(--line);
  border-radius: 18px;
  color: var(--text);
  cursor: pointer;
  padding: 16px;
  text-align: left;
}

.role-card.active,
.option-card.active,
.feedback-card.active {
  border-color: var(--cyan);
  box-shadow: 0 0 0 1px rgba(55, 215, 196, 0.25);
}

.history-row {
  align-items: center;
  border-top: 1px solid var(--line);
  color: inherit;
  display: grid;
  gap: 12px;
  grid-template-columns: 1fr auto;
  padding: 16px 0;
  text-decoration: none;
}

.history-row:first-child {
  border-top: 0;
}

.history-row span,
.note-card span {
  color: var(--muted);
  display: block;
  font-size: 13px;
}

.note-card {
  border-top: 1px solid var(--line);
  padding: 14px 0;
}

.note-card:first-child {
  border-top: 0;
}

.step-bar {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
}

.step-bar span {
  background: rgba(255, 255, 255, 0.04);
  border: 1px solid var(--line);
  border-radius: 999px;
  color: var(--muted);
  font-size: 13px;
  padding: 8px 12px;
}

.step-bar span.active {
  border-color: var(--cyan);
  color: var(--cyan);
}

.preview-box,
.success-panel {
  background: rgba(255, 255, 255, 0.04);
  border: 1px solid var(--line);
  border-radius: 18px;
  padding: 18px;
}

.inline-notice {
  background: rgba(55, 215, 196, 0.12);
  border: 1px solid rgba(55, 215, 196, 0.35);
  border-radius: 14px;
  color: var(--cyan);
  padding: 12px 16px;
}

.feedback-card.clickable {
  cursor: pointer;
}

.metric-grid.compact {
  grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
}

.prototype-table {
  display: grid;
  gap: 14px;
}

.prototype-table article {
  align-items: center;
  background: rgba(255, 255, 255, 0.04);
  border: 1px solid var(--line);
  border-radius: 18px;
  display: grid;
  gap: 16px;
  grid-template-columns: minmax(260px, 1fr) minmax(300px, 1.4fr) auto;
  padding: 16px;
}

.prototype-table h3 {
  font-size: 16px;
  line-height: 1.5;
  margin: 4px 0 0;
}

.route-list {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.route-list a {
  background: rgba(79, 163, 255, 0.12);
  border: 1px solid rgba(79, 163, 255, 0.22);
  border-radius: 999px;
  color: #bfe0ff;
  font-size: 12px;
  padding: 7px 10px;
}

.agent-row.active-row,
.question-chip.active-row {
  border-color: var(--cyan);
  box-shadow: 0 0 0 1px rgba(55, 215, 196, 0.2);
}

.stepper {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  margin: 16px 0;
}

.stepper span {
  background: rgba(255, 255, 255, 0.04);
  border: 1px solid var(--line);
  border-radius: 999px;
  color: var(--muted);
  padding: 9px 12px;
}

.stepper span.active {
  background: rgba(55, 215, 196, 0.12);
  border-color: var(--cyan);
  color: var(--cyan);
}

.dev-canvas,
.code-shell,
.mobile-stage {
  display: grid;
  gap: 18px;
  grid-template-columns: 260px 1fr 320px;
}

.code-shell {
  grid-template-columns: 1fr 360px;
}

.mobile-stage {
  grid-template-columns: 280px minmax(320px, 420px);
  justify-content: center;
}

.workflow-board {
  align-content: start;
  display: grid;
  gap: 14px;
}

.workflow-board article {
  align-items: center;
  background: rgba(255, 255, 255, 0.04);
  border: 1px solid var(--line);
  border-radius: 18px;
  cursor: pointer;
  display: grid;
  gap: 14px;
  grid-template-columns: 42px 1fr auto;
  padding: 16px;
}

.workflow-board article.active {
  border-color: var(--cyan);
}

.workflow-board article > span {
  align-items: center;
  background: rgba(55, 215, 196, 0.14);
  border-radius: 14px;
  color: var(--cyan);
  display: flex;
  font-weight: 900;
  height: 42px;
  justify-content: center;
}

.code-panel pre {
  background: rgba(2, 8, 12, 0.65);
  border: 1px solid var(--line);
  border-radius: 18px;
  color: #bfe0ff;
  line-height: 1.8;
  min-height: 360px;
  overflow: auto;
  padding: 18px;
}

.phone-frame {
  background: linear-gradient(180deg, #112b38, #061019);
  border: 10px solid #02080c;
  border-radius: 38px;
  box-shadow: 0 24px 80px rgba(0, 0, 0, 0.36);
  min-height: 720px;
  padding: 18px;
}

.phone-status,
.phone-title {
  color: var(--muted);
  font-size: 12px;
  margin-bottom: 12px;
}

.phone-title {
  color: var(--text);
  font-size: 18px;
  font-weight: 900;
}

.phone-card,
.phone-list div,
.phone-chat p,
.phone-chat strong {
  background: rgba(255, 255, 255, 0.06);
  border: 1px solid var(--line);
  border-radius: 18px;
  display: block;
  margin-bottom: 12px;
  padding: 14px;
}

.phone-card button,
.phone-list span {
  background: rgba(55, 215, 196, 0.14);
  border: 1px solid rgba(55, 215, 196, 0.24);
  border-radius: 999px;
  color: var(--cyan);
  display: inline-flex;
  margin-top: 10px;
  padding: 8px 12px;
}

.phone-list div {
  align-items: center;
  display: flex;
  justify-content: space-between;
}

.phone-list span {
  margin-top: 0;
}

@media (max-width: 1080px) {
  .app-shell,
  .two-column,
  .schedule-layout,
  .reports-layout,
  .field-layout,
  .expert-layout,
  .chat-layout,
  .three-column,
  .prototype-table article,
  .dev-canvas,
  .code-shell,
  .mobile-stage {
    grid-template-columns: 1fr;
  }

  .sidebar {
    height: auto;
    position: static;
  }
}

