  margin-left: 12px;
}

@media (max-width: 1366px) and (min-width: 1081px) {
  .app-shell {
    grid-template-columns: 48px minmax(0, 1fr);
  }

  .sidebar {
    padding: 8px 4px;
  }

  .brand {
    height: 48px;
    justify-content: center;
    margin-bottom: 8px;
    padding: 0;
  }

  .brand-mark {
    border-radius: 4px;
    flex-basis: 32px;
    height: 32px;
    width: 32px;
  }

  .brand > div:not(.brand-mark),
  .sidebar a span {
    display: none;
  }

  .sidebar a {
    gap: 0;
    height: 40px;
    justify-content: center;
    padding: 0;
  }
}

@media (max-width: 1080px) {
