    padding: 24px;
  }

  .topbar {
    align-items: flex-start;
    flex-direction: column;
    height: auto;
    margin: -24px -24px 24px;
    padding: 16px 24px;
  }

  .search-pill {
    min-width: 0;
    width: 100%;
  }

  .page-heading.split,
  .hero,
  .hero.compact,
  .section-title,
  .feedback-card,
  .expert-task,
  .action-row {
    align-items: flex-start;
    flex-direction: column;
  }

  .feedback-form,
  .device-actions {
    grid-template-columns: 1fr;
  }

  .loop-grid article:not(:last-child)::after {
    display: none;
  }
}

